package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.hq.app.person.Hold;

/** A claim of a person on a sheet: its amount with two decimals, its date (ISO yyyy-MM-dd), note and status
 *  (DRAFT, OPEN, PENDING — a clerk's settle above the clerk limit, awaiting a steward — SETTLED or VOID), its number on the sheet (a sheet-wide 1, 2, ... or, under period numbering, <period>-<n> or X-<n>; null while a draft; a voided claim keeps the one it had), and the due fixed when it was settled
 *  (null unless settled with a rate; its due is then worked out live from the rates), and who opened it
 *  (null until it is opened), whether its person's last statement bound it, and the figure it was bound to
 *  (null when not bound, or bound with no figure: its due then stays live), and, for a correction (a negative
 *  amount), the number of the settled claim it corrects (null otherwise), and its due-by (yyyy-MM-dd: fixed when it was
 *  created, its date then plus the terms of its person's grade on that date, else the sheet's terms). */
public record Claim(long id, long personId, String amount, String date, String note, String status,
        String number, String due, String openedBy, boolean stated, String statedDue, String corrects,
        String dueBy) {

    /** Whether the claim is open: OPEN, or PENDING (handled like OPEN everywhere but its statement binding). */
    public boolean open() {
        return status.equals("OPEN") || status.equals("PENDING");
    }

    /** Whether the claim counts toward claimed and every total: only open (OPEN or PENDING) and SETTLED claims do. */
    public boolean counts() {
        return open() || status.equals("SETTLED");
    }

    /** Whether the claim counts toward live totals (claimed, due-totals, a period's total) given its
     *  person's holds: an open claim dated within a hold does not, unless a statement binds it; SETTLED
     *  claims always do. */
    public boolean counts(List<Hold> holds) {
        return status.equals("SETTLED") || (open() && (bound() || !Hold.anyCovers(holds, date)));
    }

    /** Whether the claim keeps a fixed figure: its settled due, else the one its last statement bound it
     *  to — except while PENDING, when the statement does not bind it and its figure is live. */
    public boolean fixed() {
        return due != null || (bound() && statedDue != null);
    }

    /** Whether its last statement binds it now: it was stated and is not PENDING. */
    public boolean bound() {
        return stated && !status.equals("PENDING");
    }

    /** The audit field a numbered claim adds at the end of its lines: " number=<n>", or "" when it has none. */
    static String auditNumber(String number) {
        return number == null ? "" : " number=" + number;
    }
}
-- A person's statements: how many have been taken, and the last one's due-total (as shown, so
-- possibly 'n/a') and date (the sheet's today when it was taken). Null until the first statement.
ALTER TABLE person ADD COLUMN statement_count BIGINT DEFAULT 0 NOT NULL;
ALTER TABLE person ADD COLUMN stated_total VARCHAR(20);
ALTER TABLE person ADD COLUMN statement_date DATE;
-- A claim bound by its person's last statement: it shows and totals stated_due (the figure it had
-- then; null when it had none, its due then staying live) until the next statement rebinds or
-- unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(19, 2);
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { heldOn, type Hold } from '../people/usePeople';

/** A claim's status: DRAFT -> OPEN -> SETTLED; a clerk's settle above the clerk limit goes to PENDING
 *  instead, which a steward approves (SETTLED) or rejects (OPEN again); a DRAFT, OPEN or PENDING claim
 *  can become VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A claim: its amount with two decimals, its date (yyyy-mm-dd), its note, its status, its number on
 *  the sheet (given when it is opened: 1, 2, ... or, under period numbering, <period>-<n> or X-<n>; null while a draft and once void) and the due fixed when it was
 *  settled (null unless settled while its grade had a rate: its due is then live, from the rates), and
 *  who opened it (null until it is opened), whether its person's last statement bound it, and the figure
 *  it was bound to (null when not bound, or bound with no figure: its due then stays live), and, for a
 *  correction (a negative amount), the number of the settled claim of the same person it corrects, and
 *  its due-by (yyyy-mm-dd), fixed when it was created from the terms of its person's grade then (else the
 *  sheet's terms), and its status log: a line per status it has had, oldest first, as
 *  "<STATUS> by <user> on <date> due=<due>" with the sheet's today and its due at that moment. */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  due: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  dueBy: string;
  log: string[];
};

/** Whether a claim is open: OPEN, or PENDING (handled like OPEN everywhere but its statement binding). */
export function isOpen(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** A claim's fixed figure: the due frozen when it was settled, else the one its last statement bound
